#define LED_PIN 13  // Пин светодиода (встроенный светодиод на 13-м пине)

void setup() {
  pinMode(LED_PIN, OUTPUT);  // Настраиваем пин как выход
}

void loop() {
  digitalWrite(LED_PIN, HIGH);  // Включаем светодиод
  delay(random(50, 200));     // Случайная задержка от 50 до 200 мс
  digitalWrite(LED_PIN, LOW);   // Выключаем светодиод
  delay(random(100, 300));   // Случайная задержка от 100 до 300 мс
}
